Complète cette recherche dichotomique récursive dans un tableau trié t, qui renvoie True si x est présent. Trace ensuite dicho(t, 5) pour t = [1, 3, 5, 7, 9].

def dicho(t, x, g=0, d=None):
    if d is None:
        d = len(t) - 1
    if g > d:
        return False
    m = (g + d) // 2
    if t[m] == x:
        return True
    if t[m] < x:
        return dicho(t, x, m+1, d)
    return dicho(t, x, g, m-1)

